# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import contact_rows


def make_student(last, first, section, email):
    ident = "id-" + last
    return Student(ident, last, first, section, email)


class ContactRowTests(unittest.TestCase):
    def test_rows_sorted_by_name_and_aligned(self):
        students = [
            make_student("Zane", "Al", "B", "al@x.org"),
            make_student("Adams", "Beth", "A", "b@x.org")
        ]
        self.assertEqual(
            contact_rows(students),
            [
                "Adams, Beth  A  b@x.org",
                "Zane, Al     B  al@x.org"
            ]
        )

    def test_missing_email_names_the_student(self):
        students = [
            make_student("Adams", "Beth", "A", "b@x.org"),
            make_student("Kent", "Joan", "A", None)
        ]
        with self.assertRaises(ProjectError) as caught:
            contact_rows(students)
        self.assertIn("Kent, Joan", str(caught.exception))

    def test_blank_email_counts_as_missing(self):
        students = [make_student("Kent", "Joan", "A", "  ")]
        with self.assertRaises(ProjectError):
            contact_rows(students)

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])
